// 1. Builds apps-script/Pages.js from web/*.html (styles inlined) for the web app.
// 2. Concatenates apps-script/*.js into dist/ZOFF-Champions.gs for a single copy-paste install.
const fs = require('fs');

const styles = fs.readFileSync('web/styles.css', 'utf8');
const page = (f) => fs.readFileSync('web/' + f, 'utf8').replace('/*STYLES*/', () => styles);
fs.writeFileSync('apps-script/Pages.js',
  "// Generated by 'npm run bundle' from web/. Edit those files, not this one.\n" +
  'var PAGES = ' + JSON.stringify({ employee: page('employee.html'), review: page('review.html') }, null, 1) + ';\n');

const order = ['Config', 'Rules', 'Store', 'Intake', 'Leaderboard', 'MonthEnd', 'Setup', 'WebApp', 'Pages'];
const out = ['// ZOFF Champions: all Apps Script files in one. Paste into Extensions > Apps Script (Code.gs).',
  "// Generated by 'npm run bundle' from apps-script/ and web/. Edit those files, not this one."];
for (const f of order) out.push('', '// ===== ' + f + '.js =====', fs.readFileSync('apps-script/' + f + '.js', 'utf8'));
new Function(out.join('\n')); // syntax check
fs.mkdirSync('dist', { recursive: true });
fs.writeFileSync('dist/ZOFF-Champions.gs', out.join('\n'));
fs.copyFileSync('apps-script/appsscript.json', 'dist/appsscript.json');
console.log('Wrote apps-script/Pages.js and dist/ZOFF-Champions.gs');
